  "input": {
    "text": "可以固定成五步：先看是否有电气或结构危险；再写位置、范围和伴随现象；按时间比较使用、天气和通风；只做低风险观察；最后按证据决定继续记录、关水隔离或专业报修。",
    "language": "Chinese",
    "voice_setting": {
      "voice_id": "Serena",
      "seed": 4241196779,
